// SVG path strings are single-token data that cannot be wrapped without corrupting the
// geometry, so MaxLineLength is suppressed for this asset file.
@file:Suppress("MaxLineLength")

package com.stratum.core.ui.component.musclepicker

import com.stratum.domain.onboarding.MuscleGroup

/**
 * SVG path geometry for the body-map muscle picker, ported from the MIT-licensed
 * `react-native-body-highlighter` (see LICENSE in this package) and re-serialized via
 * `svg.path` so every path string is in canonical, [androidx.core.graphics.PathParser]-safe
 * form (arc flags separated, all tokens space-delimited). The upstream source used
 * SVG-legal-but-Android-incompatible shorthand (concatenated arc flags like `01`); the
 * geometry is identical, only the textual representation was normalized offline.
 *
 * Coordinate systems differ between front and back views (the source centered each view
 * independently), so [com.stratum.core.ui.component.StratumMusclePicker] normalizes each
 * view's bounding box into its Canvas at draw time rather than assuming a shared space.
 *
 * Region mapping (see [BodyRegion.target]):
 *  - chest -> Chest, upper-back -> Back, quadriceps -> Quad, hamstring -> Hamstring,
 *    gluteal -> Glute, triceps -> Tricep, biceps -> Bicep, trapezius -> Trap,
 *    calves -> Calf, forearm -> Forearm, abs+obliques -> Ab, lower-back -> LowerBack,
 *    deltoids -> [DeltoidRegion] (resolved by the sub-picker into the three deltoid heads).
 *  - Upstream slugs with no MuscleGroup counterpart (neck, head, hands, feet, knees,
 *    adductors, tibialis, ankles, hair) are dropped.
 */

/** A tap target on the body map: either a single muscle group or the composite deltoids. */
internal sealed interface BodyTarget {
    @JvmInline
    value class Single(val muscle: MuscleGroup) : BodyTarget
    data object DeltoidRegion : BodyTarget
}

internal data class BodyRegion(
    val target: BodyTarget,
    val leftPaths: List<String>,
    val rightPaths: List<String>,
)

